(()=>{const widgets=[{"title":"12-player Raptor grid","file":"gui_metal_plate_12_player_raptor_line_grid_draw.lua","author":"Lu5ck","desc":"Your supplied grid for Full Metal Plate. Use this instead of the older grid widget.","data":""},{"title":"Base Layout Planner","file":"LayoutPlanner.lua","author":"Noryon","desc":"Plan, save and load your own base layouts. Saved personal layouts are not included.","data":""},{"title":"NuttyB Raptor Panel","file":"gui_raptor_panel_aggro.lua","author":"quantum, tetrisface","desc":"Raptor progress, statistics and eco attraction. For Raptors and Scavengers.","data":""},{"title":"Phoenix Engine","file":"phoenix_engine.lua","author":"timuela","desc":"Reclaims blocking units when placing buildings over them.","data":""},{"title":"Tweakdefs Bridge","file":"Tweakdefs_bridge.lua","author":"Ambo","desc":"Displays custom unit names and descriptions. Alt+M toggles custom names.","data":""}];
const root=document.getElementById('widgets');
root.innerHTML='<h2>Your NuttyB toolkit</h2><p class="hint">Widgets from Will’s game setup, with author credits and a few useful community finds.</p><div class="widget-install"><strong>Install in three steps</strong><br>1. In the BAR launcher, choose Open Install Directory.<br>2. Put the downloaded .lua files in <strong>data / LuaUI / Widgets</strong>.<br>3. In game, open Settings → Custom → Widgets and enable them.<br><small>Use only one version of each widget. Disable the old grid before using this supplied grid. Community extras have not been tested in this setup.</small></div><p><a class="widget-link" href="blackouts-widget-pack.zip" download>Download widget pack</a></p><div class="widget-grid" id="widget-local"></div><h2 class="widget-section-title">Reclaim & build helpers</h2><div class="widget-grid" id="widget-linked"></div><h2 class="widget-section-title">More community widgets</h2><p class="hint">Get these from their original authors. Check their installation notes for the latest version.</p><div class="widget-grid" id="widget-extra"></div>';
function card(target,title,author,desc){const box=document.createElement('article');box.className='widget-card';for(const [tag,text]of [['h3',title],['small','By '+author],['p',desc]]){const child=document.createElement(tag);child.textContent=text;box.appendChild(child);}document.getElementById(target).appendChild(box);return box;}
for(const widget of widgets){const box=card('widget-local',widget.title,widget.author,widget.desc);const button=document.createElement('button');button.className='primary';button.textContent='Download widget';button.addEventListener('click',()=>{const bytes=Uint8Array.from(atob(widget.data),c=>c.charCodeAt(0));const url=URL.createObjectURL(new Blob([bytes],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download=widget.file;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);});box.appendChild(button);}
const sources={ 'LayoutPlanner.lua':'https://github.com/noryon/BARLayoutPlanner', 'gui_raptor_panel_aggro.lua':'https://gist.github.com/tetrisface/2f99f5a5b179e3ac42e7e63825880713', 'gui_metal_plate_12_player_raptor_line_grid_draw.lua':'https://github.com/tetrisface/community-widgets/tree/main/gui_metal_plate_12_player_raptor_line_grid_draw' };
for(let i=0;i<widgets.length;i++){const url=sources[widgets[i].file];if(url){const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener noreferrer';a.textContent='Creator’s page ↗';a.style.color='#88b9ff';document.getElementById('widget-local').children[i].appendChild(a);}}
const links=[
 ['widget-linked','Reclaim Selected','manshanko','Reclaim selected units using nearby nano turrets. The author requests sharing through their page.','https://github.com/manshanko/bar-widgets#reclaim-selected'],
 ['widget-linked','Holo Place / No hijack','augustin, manshanko','Building assistance tools. Your installed no-hijack variant is disabled by default; choose one version.','https://github.com/manshanko/bar-widgets#holo-place'],
 ['widget-extra','Metal Tracker','Chin','Track resources that teammates send to you.','https://github.com/DrChinny/BAR-Widgets/blob/main/metal_tracker.lua'],
 ['widget-extra','Energy Conversion Meter','Egzothicki','See the balance between energy production and conversion.','https://github.com/beyond-all-reason/BAR-Widgets/tree/main/Widgets/community/gui_energy_conversion_meter'],
 ['widget-extra','Track Sabotage','manshanko','Local notifications when friendly fire destroys economy units.','https://github.com/manshanko/bar-widgets#track-sabotage']
];
for(const [target,title,author,desc,url]of links){const box=card(target,title,author,desc);const a=document.createElement('a');a.className='widget-link';a.href=url;a.target='_blank';a.rel='noopener noreferrer';a.textContent='Get from author ↗';box.appendChild(a);}
const ids=['configuration','commands','custom','widgets'];
for(const id of ids)document.getElementById(id+'-tab').addEventListener('click',()=>{root.hidden=id!=='widgets';if(id==='widgets'){document.getElementById('configuration').hidden=true;document.getElementById('outputs').hidden=true;document.getElementById('custom').hidden=true;}for(const tab of ids){const button=document.getElementById(tab+'-tab');button.classList.toggle('active',tab===id);button.setAttribute('aria-pressed',String(tab===id));}});

})();